(5656668, 820765, 81362, '<td valign="top">Using light to show the texture works pretty well here. Stack seems oddly off, maybe leaning towards us a little.</td>', 'Using light to show the texture works pretty well here. Stack seems oddly off, maybe leaning towards us a little.', '2009-09-21 23:26:03.000000', NULL, 1),
(5656670, 821338, 81362, '<td valign="top">Bright colors work well against the dark backgroud. Lack of three dimensional cues contributes to a graphic effect, like a cartoon or painting.</td>', 'Bright colors work well against the dark backgroud. Lack of three dimensional cues contributes to a graphic effect, like a cartoon or painting.', '2009-09-21 23:27:34.000000', NULL, 1),
