(5657827, 821576, 80780, '<td valign="top">nice expression, but seems like a shoehorn.</td>', 'nice expression, but seems like a shoehorn.', '2009-09-22 19:55:55.000000', NULL, 1),
(5657829, 821454, 80780, '<td valign="top">Out of focus, blurry, and shoe horned.</td>', 'Out of focus, blurry, and shoe horned.', '2009-09-22 19:56:08.000000', NULL, 1),
(5657830, 821476, 80780, '<td valign="top">Great product shot. Nice separation, nice lighting, and it looks like you avoided ending up in the refection. Great work.</td>', 'Great product shot. Nice separation, nice lighting, and it looks like you avoided ending up in the refection. Great work.', '2009-09-22 19:56:42.000000', NULL, 1),
(5657831, 821397, 80780, '<td valign="top">Im surprised we didn''t see more of this in this challenge. Great idea and nice set up.</td>', 'Im surprised we didn''t see more of this in this challenge. Great idea and nice set up.', '2009-09-22 19:57:18.000000', NULL, 1),
(5657832, 821534, 80780, '<td valign="top">Kind of underwhelming.</td>', 'Kind of underwhelming.', '2009-09-22 19:57:30.000000', NULL, 1),
(5657833, 821554, 80780, '<td valign="top">Man the texture on that recycled paper and the imperfection of the numbers makes this an awesome image for me. Good work.</td>', 'Man the texture on that recycled paper and the imperfection of the numbers makes this an awesome image for me. Good work.', '2009-09-22 19:57:53.000000', NULL, 1),
(5657834, 821266, 80780, '<td valign="top">Nice shot but im allergic to chocolate so 1!<br/> <br/>Not really.</td>', 'Nice shot but im allergic to chocolate so 1! Not really.', '2009-09-22 19:58:36.000000', NULL, 1),
(5657836, 820600, 80780, '<td valign="top">CZ? Nice prouct shot and I think the shallow dof really works great on this.</td>', 'CZ? Nice prouct shot and I think the shallow dof really works great on this.', '2009-09-22 19:59:04.000000', NULL, 1),
(5657839, 820517, 80780, '<td valign="top">The motion blur on this is awesome. Great shot. And billiards was the first thing that came to mind for me on this challenge.</td>', 'The motion blur on this is awesome. Great shot. And billiards was the first thing that came to mind for me on this challenge.', '2009-09-22 19:59:35.000000', NULL, 1),
(5657841, 821394, 80780, '<td valign="top">Beautiful picture but a shoe horn, so 1.</td>', 'Beautiful picture but a shoe horn, so 1.', '2009-09-22 19:59:57.000000', NULL, 1),
