(5657847, 821384, 80780, '<td valign="top">nice set up, and nice lawn.</td>', 'nice set up, and nice lawn.', '2009-09-22 20:01:36.000000', NULL, 1),
(5657849, 821001, 80780, '<td valign="top">This will be in the top 3 I bet. Great image. Perfect. Wow. One of the best ive seen on DPC to be honest. 10 easily.</td>', 'This will be in the top 3 I bet. Great image. Perfect. Wow. One of the best ive seen on DPC to be honest. 10 easily.', '2009-09-22 20:02:09.000000', NULL, 1),
