(5657865, 820972, 80780, '<td valign="top">Nice texture and way to flash it so you didn''t lose it all.</td>', 'Nice texture and way to flash it so you didn''t lose it all.', '2009-09-22 20:07:02.000000', NULL, 1),
(5657866, 821251, 80780, '<td valign="top">Nice shot, but I dont see 9? Or is 5 petals and then 5 leaves?</td>', 'Nice shot, but I dont see 9? Or is 5 petals and then 5 leaves?', '2009-09-22 20:07:45.000000', NULL, 1),
(5657868, 820674, 80780, '<td valign="top">Good idea, but I think the execution is weak.</td>', 'Good idea, but I think the execution is weak.', '2009-09-22 20:08:08.000000', NULL, 1),
(5657870, 820773, 80780, '<td valign="top">I see where you were going, but I think you went too far. Also I think a tighter crop to cut out some of that additonal black space would have helped.</td>', 'I see where you were going, but I think you went too far. Also I think a tighter crop to cut out some of that additonal black space would have helped.', '2009-09-22 20:08:48.000000', NULL, 1),
(5657872, 821467, 80780, '<td valign="top">Not sure what im looking at, but its neat.</td>', 'Not sure what im looking at, but its neat.', '2009-09-22 20:09:08.000000', NULL, 1),
(5657873, 821511, 80780, '<td valign="top">Nice grunge, but nothing too interesting.</td>', 'Nice grunge, but nothing too interesting.', '2009-09-22 20:09:34.000000', NULL, 1),
(5657875, 821269, 80780, '<td valign="top">Great shot, but that little starburst blow out is killing me! Overall I like it, and its one of the better clock shots in this challenge.</td>', 'Great shot, but that little starburst blow out is killing me! Overall I like it, and its one of the better clock shots in this challenge.', '2009-09-22 20:10:06.000000', NULL, 1),
