INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5657977, 821612, 110186, '<td valign="top">Neat picture!</td>', 'Neat picture!', '2009-09-22 21:03:51.000000', NULL, 1),
(5657978, 821599, 110186, '<td valign="top">Interesting!</td>', 'Interesting!', '2009-09-22 21:04:16.000000', NULL, 1),
(5657980, 821528, 110186, '<td valign="top">Hope all goes well, and congrats to your model! :)</td>', 'Hope all goes well, and congrats to your model! :)', '2009-09-22 21:04:40.000000', NULL, 1),
(5657984, 820933, 110186, '<td valign="top">...and with 9 orange flowers to boot! :)</td>', '...and with 9 orange flowers to boot! :)', '2009-09-22 21:05:10.000000', NULL, 1),
(5658016, 820839, 110186, '<td valign="top">Looks yummy!</td>', 'Looks yummy!', '2009-09-22 21:17:35.000000', NULL, 1),
(5658018, 821603, 110186, '<td valign="top">Cute title!</td>', 'Cute title!', '2009-09-22 21:18:09.000000', NULL, 1),
(5658021, 821423, 110186, '<td valign="top">That looks quite yummy!</td>', 'That looks quite yummy!', '2009-09-22 21:19:31.000000', NULL, 1),
(5658169, 821338, 67697, '<td valign="top">Very pretty.  I love the splatter of petals.  Gorgeous vibrant color too.</td>', 'Very pretty.  I love the splatter of petals.  Gorgeous vibrant color too.', '2009-09-22 23:48:32.000000', NULL, 1),
(5658171, 821124, 67697, '<td valign="top">There''s something really cool about this photo.  I love this in black and white and how the white kitty just pops out of the scene.  Only nitpick is the kitty inhaling the weeds lol.  But I guess you can''t do much about it since cats have a mind of their own. :)</td>', 'There''s something really cool about this photo.  I love this in black and white and how the white kitty just pops out of the scene.  Only nitpick is the kitty inhaling the weeds lol.  But I guess you can''t do much about it since cats have a mind of their own. :)', '2009-09-22 23:50:08.000000', NULL, 1),
(5658172, 821414, 67697, '<td valign="top">Very clever.  I kept counting lol.  I''m not a fan of the colortone but I love the concept.</td>', 'Very clever.  I kept counting lol.  I''m not a fan of the colortone but I love the concept.', '2009-09-22 23:50:48.000000', NULL, 1),
(5658173, 821451, 67697, '<td valign="top">I love how you''ve tucked the number into the lines and blurs.  Beautiful combination of colors.</td>', 'I love how you''ve tucked the number into the lines and blurs.  Beautiful combination of colors.', '2009-09-22 23:52:21.000000', NULL, 1),
(5658176, 820961, 81362, '<td valign="top">White done very well, makes me think of exceptionally strong mints.</td>', 'White done very well, makes me think of exceptionally strong mints.', '2009-09-22 23:52:58.000000', NULL, 1),
(5658181, 821348, 47470, '<td valign="top">I love the spark that''s bouncing on the bottom!  Great idea!</td>', 'I love the spark that''s bouncing on the bottom!  Great idea!', '2009-09-22 23:55:16.000000', NULL, 1),
(5658182, 821564, 67697, '<td valign="top">I love the simplicity of the shot.  I like the beauty in the every-day kinds of things.  Great capture of light too.</td>', 'I love the simplicity of the shot.  I like the beauty in the every-day kinds of things.  Great capture of light too.', '2009-09-22 23:55:25.000000', NULL, 1),
(5658185, 821431, 67697, '<td valign="top">This is cool.  I love the light on the bottle too.</td>', 'This is cool.  I love the light on the bottle too.', '2009-09-22 23:56:19.000000', NULL, 1),
(5658186, 821467, 67697, '<td valign="top">This is cool - what is it?  Love the artsy look.</td>', 'This is cool - what is it?  Love the artsy look.', '2009-09-22 23:56:57.000000', NULL, 1),
(5658187, 821511, 81362, '<td valign="top">Scratched metal surface, grunge, and title all suggestive of a depressing institutional setting. Will be interesting to see how this does.</td>', 'Scratched metal surface, grunge, and title all suggestive of a depressing institutional setting. Will be interesting to see how this does.', '2009-09-22 23:57:15.000000', NULL, 1),
(5658189, 820451, 67697, '<td valign="top">Maybe they are waiting for the Harry Potter train?  :D  What an interesting group to capture.  Wonder who belongs to all that luggage :)</td>', 'Maybe they are waiting for the Harry Potter train?  :D  What an interesting group to capture.  Wonder who belongs to all that luggage :)', '2009-09-22 23:59:00.000000', NULL, 1),
(5658191, 820863, 47470, '<td valign="top">I wish the lighting had come more from the side to help bring out all the detail in the wood and emphasize the metal even more.</td>', 'I wish the lighting had come more from the side to help bring out all the detail in the wood and emphasize the metal even more.', '2009-09-23 00:00:40.000000', NULL, 1),
(5658196, 821461, 47470, '<td valign="top">The hardest thing about photographing something flat, is well, it''s flat, so it''s hard to give it some depth.  You tried to do this with the depth of field, but I''m not sure you were successful.  The part in focus is so close to the edge that my eye wanders.  Bringing up the contrast (the whites in this aren''t white at all, but middle gray) and adding something 3D, like the marker or an abacus or something would have strengthened this image.</td>', 'The hardest thing about photographing something flat, is well, it''s flat, so it''s hard to give it some depth.  You tried to do this with the depth of field, but I''m not sure you were successful.  The part in focus is so close to the edge that my eye wanders.  Bringing up the contrast (the whites in this aren''t white at all, but middle gray) and adding something 3D, like the marker or an abacus or something would have strengthened this image.', '2009-09-23 00:04:09.000000', NULL, 1),
(5658199, 821424, 67697, '<td valign="top">Simple and yet eye-catching.  Love the use of DOF.</td>', 'Simple and yet eye-catching.  Love the use of DOF.', '2009-09-23 00:05:47.000000', NULL, 1),
(5658201, 820926, 47470, '<td valign="top">Great sharpness and depth of field, but I think it would be interesting to leave more negative space above (maybe below, but I think I''d prefer above) to both emphasize the smallness of the subject, but also to move the subject out from the center.</td>', 'Great sharpness and depth of field, but I think it would be interesting to leave more negative space above (maybe below, but I think I''d prefer above) to both emphasize the smallness of the subject, but also to move the subject out from the center.', '2009-09-23 00:06:00.000000', NULL, 1),
(5658202, 820863, 67697, '<td valign="top">I love how you captured the detail on the spring and on the wood.</td>', 'I love how you captured the detail on the spring and on the wood.', '2009-09-23 00:07:13.000000', NULL, 1),
(5658203, 821456, 67697, '<td valign="top">I wish it were spring here!  :)  I love the combination of metal and plants.  Good eye for seeing the 9.</td>', 'I wish it were spring here!  :)  I love the combination of metal and plants.  Good eye for seeing the 9.', '2009-09-23 00:08:27.000000', NULL, 1),
(5658204, 821603, 67697, '<td valign="top">Hilarious - I didn''t even notice what the one in front was doing the first time around.  Great timing!</td>', 'Hilarious - I didn''t even notice what the one in front was doing the first time around.  Great timing!', '2009-09-23 00:09:16.000000', NULL, 1),
(5658205, 821436, 47470, '<td valign="top">I''m not terribly sure if I understand the connection between the date 9/9/09 and Wizard of Oz.  I''ll have to read the Photog''s Comments when the challenge is over.<br/> <br/>Photos of toys don''t generally socre very well here on DPC unless there is something spectacular about it.  I think this would look a bit more interesting if there was more depth to the light instead of the soft, overall light you have used.  Some directional light on the man and 9s with a darker background might add some pop.</td>', 'I''m not terribly sure if I understand the connection between the date 9/9/09 and Wizard of Oz.  I''ll have to read the Photog''s Comments when the challenge is over. Photos of toys don''t generally socre very well here on DPC unless there is something spectacular about it.  I think this would look a bit more interesting if there was more depth to the light instead of the soft, overall light you have used.  Some directional light on the man and 9s with a darker background might add some pop.', '2009-09-23 00:10:36.000000', NULL, 1),
(5658207, 821275, 67697, '<td valign="top">Trippy!  Fun looking blur too.  Did you use a glass or a mirror?  Interesting idea.</td>', 'Trippy!  Fun looking blur too.  Did you use a glass or a mirror?  Interesting idea.', '2009-09-23 00:11:14.000000', NULL, 1),
(5658209, 821567, 47470, '<td valign="top">I think this image has a lot of potential.  It''s technically sound, but I think it would be a bit bolder if you darkened the blacks and ran this through Topaz (or a similar program) to bring out some grungy detail of the cement.  Vignettes are illegal under this editing set, but if you want to work on this image some more once the challenge is over, I think a vignette would be another thing to add.</td>', 'I think this image has a lot of potential.  It''s technically sound, but I think it would be a bit bolder if you darkened the blacks and ran this through Topaz (or a similar program) to bring out some grungy detail of the cement.  Vignettes are illegal under this editing set, but if you want to work on this image some more once the challenge is over, I think a vignette would be another thing to add.', '2009-09-23 00:14:27.000000', NULL, 1),
(5658213, 820600, 47470, '<td valign="top">Wonderful depth of field.  I love that you chose a cyan background to complement the gold, but I think I might have made it ever so slightly more saturated.</td>', 'Wonderful depth of field.  I love that you chose a cyan background to complement the gold, but I think I might have made it ever so slightly more saturated.', '2009-09-23 00:16:04.000000', NULL, 1),
(5658216, 821575, 67697, '<td valign="top">Very pretty.  I love the soft colors.  The points of blur add extra interest too.</td>', 'Very pretty.  I love the soft colors.  The points of blur add extra interest too.', '2009-09-23 00:19:13.000000', NULL, 1),
(5658218, 821465, 47470, '<td valign="top">Because of the low camera angle and shallow depth of field, it is very difficult to see the nine.  I''m not sure what the nine is made of, but I''m wondering your reason for using it.  Having it somehow connect with the idea of "9" would have made it ok that the nine is hard to see, and would have strengthened the image.  The light is very pretty, especially in the part that is in focus.  Lighting is half the battle, so now that you know where to find some great light, you''ll have to think of other great subjects to put in it! : )</td>', 'Because of the low camera angle and shallow depth of field, it is very difficult to see the nine.  I''m not sure what the nine is made of, but I''m wondering your reason for using it.  Having it somehow connect with the idea of "9" would have made it ok that the nine is hard to see, and would have strengthened the image.  The light is very pretty, especially in the part that is in focus.  Lighting is half the battle, so now that you know where to find some great light, you''ll have to think of other great subjects to put in it! : )', '2009-09-23 00:20:06.000000', NULL, 1),
(5658220, 821607, 47470, '<td valign="top">This is a very nice picture, but without the title, I don''t think the idea of "9" would have come through.  Your BnW conversion is well done, but I think the sharpening is a bit strong, particularly on her arm (there is a very noticeable halo).</td>', 'This is a very nice picture, but without the title, I don''t think the idea of "9" would have come through.  Your BnW conversion is well done, but I think the sharpening is a bit strong, particularly on her arm (there is a very noticeable halo).', '2009-09-23 00:22:19.000000', NULL, 1),
(5658221, 821229, 67697, '<td valign="top">I don''t know why, but I feel like this would look good hanging on the wall of a fancy restaurant.   I love the misty background.  I assumed there were nine oars but now I see the number 9.  I didn''t see that the first time around.  Cool shot.</td>', 'I don''t know why, but I feel like this would look good hanging on the wall of a fancy restaurant.   I love the misty background.  I assumed there were nine oars but now I see the number 9.  I didn''t see that the first time around.  Cool shot.', '2009-09-23 00:23:35.000000', NULL, 1),
(5658222, 821554, 5585, '<td valign="top">My Favorite of the Challenge...</td>', 'My Favorite of the Challenge...', '2009-09-23 00:24:11.000000', NULL, 1),
(5658225, 820883, 47470, '<td valign="top">The lighting on this is very pretty, but I wish there was a bit more contrast, especially on the brighter parts of the image.  You could use curves to open up the highlights to make them white (as they are now, the brightest part of the image is middle gray, not white).</td>', 'The lighting on this is very pretty, but I wish there was a bit more contrast, especially on the brighter parts of the image.  You could use curves to open up the highlights to make them white (as they are now, the brightest part of the image is middle gray, not white).', '2009-09-23 00:25:08.000000', NULL, 1),
(5658227, 821616, 47470, '<td valign="top">I think desaturating the yellows a bit would emphasize the blue/cyan of the tower beams.</td>', 'I think desaturating the yellows a bit would emphasize the blue/cyan of the tower beams.', '2009-09-23 00:27:21.000000', NULL, 1),
(5658229, 821583, 47470, '<td valign="top">Darkening the blacks would help give this image some depth.  Since the geese are in the center of the frame, the divide the image in half, making my eye bounce between the top half and the bottom.  Putting them on a third line would help place more focus on the birds, which would strengthen this image.</td>', 'Darkening the blacks would help give this image some depth.  Since the geese are in the center of the frame, the divide the image in half, making my eye bounce between the top half and the bottom.  Putting them on a third line would help place more focus on the birds, which would strengthen this image.', '2009-09-23 00:29:25.000000', NULL, 1),
(5658231, 821398, 47470, '<td valign="top">I''m sure you cut off the bottom of the image because you are hiding whatever is holding up the matches, but I think the image would be stronger if the match box was more prominent in the frame, both to add some color/take away some of the white and to put the bulk of the detail in the same place.   As it is now, my eye wants to bounce between the match heads and the box.</td>', 'I''m sure you cut off the bottom of the image because you are hiding whatever is holding up the matches, but I think the image would be stronger if the match box was more prominent in the frame, both to add some color/take away some of the white and to put the bulk of the detail in the same place.   As it is now, my eye wants to bounce between the match heads and the box.', '2009-09-23 00:32:16.000000', NULL, 1),
(5658235, 821229, 47470, '<td valign="top">Gorgeous image.  It almost looks like the nine (on a rock??) was pasted into the scene.  I know you need the 9 to meet the challenge, but this would be a beautiful image without it!  I''d consider cloning it out later on and keeping the rest as a stand alone image : )</td>', 'Gorgeous image.  It almost looks like the nine (on a rock??) was pasted into the scene.  I know you need the 9 to meet the challenge, but this would be a beautiful image without it!  I''d consider cloning it out later on and keeping the rest as a stand alone image : )', '2009-09-23 00:34:48.000000', NULL, 1),
(5658237, 821577, 47470, '<td valign="top">I think some moody lighting would make this image pop.  Guns, high-stake poker game, cowboys, and the wild west are all subjects that invoke tension, but the lighting is very peaceful, neutral, and calm.  Give me some directional light and maybe even some smoke!  Make me believe I''m right there with ol'' Billy!</td>', 'I think some moody lighting would make this image pop.  Guns, high-stake poker game, cowboys, and the wild west are all subjects that invoke tension, but the lighting is very peaceful, neutral, and calm.  Give me some directional light and maybe even some smoke!  Make me believe I''m right there with ol'' Billy!', '2009-09-23 00:38:23.000000', NULL, 1),
(5658239, 821335, 47470, '<td valign="top">Focus is on the 7, not 9 : )</td>', 'Focus is on the 7, not 9 : )', '2009-09-23 00:39:40.000000', NULL, 1),
(5658241, 821570, 47470, '<td valign="top">The light is much to straight on.  Bringing the light from the side and blocking it from hitting the background would have made the 9 stand out much more and added some depth to the overall image.</td>', 'The light is much to straight on.  Bringing the light from the side and blocking it from hitting the background would have made the 9 stand out much more and added some depth to the overall image.', '2009-09-23 00:40:49.000000', NULL, 1),
(5658244, 821106, 47470, '<td valign="top">Wonderful location, but why did you choose to use eggs?  Having the subject connect more with the concept would have made this image even stronger.</td>', 'Wonderful location, but why did you choose to use eggs?  Having the subject connect more with the concept would have made this image even stronger.', '2009-09-23 00:42:01.000000', NULL, 1),
(5658245, 821506, 47470, '<td valign="top">Wonderful lighting and colors!  Love the almost square crop too!</td>', 'Wonderful lighting and colors!  Love the almost square crop too!', '2009-09-23 00:43:02.000000', NULL, 1),
(5658248, 820451, 47470, '<td valign="top">A shallower depth of field would have made this a little less cluttered.</td>', 'A shallower depth of field would have made this a little less cluttered.', '2009-09-23 00:44:57.000000', NULL, 1),
(5658254, 821553, 47470, '<td valign="top">With such lovely wood, this should have some gorgeous side lighting to bring out all of that detail and texture!  Flat lighting doesn''t do it justice : )  I''d also love to see a shallower depth of field to blur out the background to keep the focus of the birdhouses.</td>', 'With such lovely wood, this should have some gorgeous side lighting to bring out all of that detail and texture!  Flat lighting doesn''t do it justice : )  I''d also love to see a shallower depth of field to blur out the background to keep the focus of the birdhouses.', '2009-09-23 00:49:05.000000', NULL, 1),
(5658256, 821455, 47470, '<td valign="top">This looks a little blown out, particularly on the sides of the dominoes (check next to the pink seven).  Nice use of the tilted horizon.</td>', 'This looks a little blown out, particularly on the sides of the dominoes (check next to the pink seven).  Nice use of the tilted horizon.', '2009-09-23 00:51:04.000000', NULL, 1),
