(5658830, 821487, 103601, '<td valign="top">sigh... just more proof that people fly through voting like it''s a race. i thought this was a great entry and i really think it should have done way better.</td>', 'sigh... just more proof that people fly through voting like it''s a race. i thought this was a great entry and i really think it should have done way better.', '2009-09-23 08:44:51.000000', NULL, 0),
(5658834, 821451, 18450, '<td valign="top">Beautiful colours and composition! Congrats on your well deserved ribbon Irene!!! You are an inspiration (((hugs)))</td>', 'Beautiful colours and composition! Congrats on your well deserved ribbon Irene!!! You are an inspiration (((hugs)))', '2009-09-23 08:49:08.000000', NULL, 0),
(5658837, 820702, 18450, '<td valign="top">Wicked shot!!! Congratulations!</td>', 'Wicked shot!!! Congratulations!', '2009-09-23 08:50:30.000000', NULL, 0),
